    # The intended stripe direction combines the clues into the fewest complete lines.
    _, _, ar, ac, groups = min(candidates, key=lambda x: (x[0], x[2] == 0))
    levels = sorted(groups)

    # Infer the shortest repeating stripe cycle consistent with every observed line.
    period = None
    for p in range(1, max(h, w) * 2 + 1):
